def compute(vars):
    old_revenue = vars["v1"]
    new_revenue = vars["v2"]

    if old_revenue == 0:
        return None

    change_ratio = (new_revenue - old_revenue) / old_revenue
    value = change_ratio * 100

    return {
        "value": value,
        "trace": {
            "old_revenue": old_revenue,
            "new_revenue": new_revenue,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
